/**
 * Times as the player writes them: "26:58", "1:02:03", "−15:12", "+0.3 s".
 * Every figure is shown with tabular numbers, so these never jump.
 */

/** U+2212, the minus sign the design uses (a hyphen is too short beside digits). */
export const MINUS = '−';

/** "26:58" under an hour, "1:02:03" from one; never negative, never NaN. */
export function clock(seconds: number): string {
  const s = Number.isFinite(seconds) && seconds > 0 ? Math.floor(seconds) : 0;
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = s % 60;
  const ss = String(sec).padStart(2, '0');
  if (h > 0) return `${h}:${String(m).padStart(2, '0')}:${ss}`;
  return `${m}:${ss}`;
}

/** The time left, as the time readout shows it when clicked: "−15:12". */
export function remaining(position: number, duration: number): string {
  return `${MINUS}${clock(Math.max(0, duration - position))}`;
}

/** "26:59.8": the sync picker's frozen moment, to a tenth. */
export function clockTenths(seconds: number): string {
  const s = Number.isFinite(seconds) && seconds > 0 ? seconds : 0;
  const tenths = Math.floor((s * 10) % 10);
  return `${clock(s)}.${tenths}`;
}

/** A subtitle's offset: "+0.3 s", "0.0 s", "−1.8 s" (ms in, tenths out). */
export function offsetLabel(ms: number): string {
  const tenths = Math.round(ms / 100);
  if (tenths === 0) return '0.0 s';
  const sign = tenths > 0 ? '+' : MINUS;
  return `${sign}${(Math.abs(tenths) / 10).toFixed(1)} s`;
}

/** Whole minutes left, rounded up, for "12 min left" (at least 1 while anything is left). */
export function minutesLeft(position: number, duration: number): number {
  const left = Math.max(0, duration - position);
  return left <= 0 ? 0 : Math.max(1, Math.ceil(left / 60));
}

/**
 * The parts of a time a screen reader says: hours, minutes and seconds, so
 * the seek slider can read "26 minutes 58 seconds of 42 minutes 10 seconds".
 */
export function spokenParts(seconds: number): { hours: number; minutes: number; seconds: number } {
  const s = Number.isFinite(seconds) && seconds > 0 ? Math.floor(seconds) : 0;
  return { hours: Math.floor(s / 3600), minutes: Math.floor((s % 3600) / 60), seconds: s % 60 };
}
